export async function retrieveEmbedding(query, memoryHierarchy) {
  const hotCache = memoryHierarchy.getHotCache();
  if (hotCache.has(query)) {
    return hotCache.get(query);
  }
  const distributedCache = memoryHierarchy.getDistributedCache();
  const embedding = await distributedCache.retrieve(query);
  hotCache.set(query, embedding);
  return embedding;
}

export function setupMemoryHierarchy(config) {
  const hotCache = new InMemoryCache(config.hotCacheSize);
  const distributedCache = new PubSubDistributedCache(config.pubSubConfig);
  return {
    getHotCache: () => hotCache,
    getDistributedCache: () => distributedCache
  };
}